#!/usr/bin/env bash
#
# Wanheda deploy setup (Phase 0, SPEC T20): the steps only the owner can do.
# Run from the repo root (main checkout or a worktree): bash scripts/setup-deploy.sh
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets these two at the top of the stages section.
TOTAL_STAGES=0
TOTAL_MINUTES=0

_STAGE_INDEX=0
_MINUTES_ELAPSED=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does and how long it takes.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages · about %s minutes%s\n\n' \
    "$DIM" "$TOTAL_STAGES" "$TOTAL_MINUTES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" <minutes> — clear the screen, then announce a stage and show
# progress + time remaining. Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  local remaining=$((TOTAL_MINUTES - _MINUTES_ELAPSED))
  (( remaining < 0 )) && remaining=0
  _MINUTES_ELAPSED=$((_MINUTES_ELAPSED + ${2:-0}))
  printf '\n%s%s▸ Stage %s/%s · %s%s  %s(~%s min left)%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET" "$DIM" "$remaining" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set the two totals to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

#
# What this sets up (SPEC T20, ADR-0002, ADR-0003, ADR-0010):
#   - two GitHub OAuth apps, one for localhost and one for production (an OAuth
#     app has exactly one callback URL)
#   - the Vercel project, linked to this repo, production deploys from main
#   - DATABASE_URL(_UNPOOLED) and the auth variables in Vercel Production only
#   - the local auth variables in the main checkout's .env.local
#
# Previews get NO database and NO auth variables, so they run demo mode on seed
# data (SPEC C12, ADR-0002). Vercel builds every pushed branch, reviewed or not,
# and a Neon preview branch would be a full copy of production's rows. The
# wizard fails if Preview ever holds any of these variables.
#
# Production secrets go to Vercel only. They are never written to .env.local
# and never printed.

TOTAL_STAGES=8
TOTAL_MINUTES=18

# Must never reach Vercel Preview (SPEC C12).
PREVIEW_FORBIDDEN="DATABASE_URL DATABASE_URL_UNPOOLED BETTER_AUTH_SECRET BETTER_AUTH_URL GITHUB_CLIENT_ID GITHUB_CLIENT_SECRET OWNER_EMAILS"

PROJECT_NAME="wanheda"
LOCAL_URL="http://localhost:3000"
CALLBACK_PATH="/api/auth/callback/github"

# .env.local lives in the main checkout (worktrees share its git dir).
MAIN_ROOT=$(dirname "$(git rev-parse --path-format=absolute --git-common-dir)")
ENV_FILE="${WANHEDA_ENV_FILE:-$MAIN_ROOT/.env.local}"

# host_of URL — the host of a connection string, without user or password.
# Prints only on a match, so an odd value can never echo its password.
host_of() {
  local host
  # Greedy userinfo: everything up to the LAST "@" before the first "/", so a
  # raw "@", "#" or "?" in a password can't leak into the "host".
  host=$(printf '%s' "$1" | tr -d "\"'" | sed -nE 's#^[a-z]+://([^/]*@)?([^/:?#]+).*#\2#p')
  printf '%s' "${host:-(unrecognised URL)}"
}

# vercel_env_set NAME VALUE [sensitive] — add a Production variable in Vercel;
# on a clash, ask before overwriting it. The value goes over stdin, never on the
# command line. Sensitive values cannot be read back from Vercel.
vercel_env_set() {
  local name="$1" value="$2" flags=(--yes --cwd "$MAIN_ROOT")
  [[ "${3:-}" == "sensitive" ]] && flags+=(--sensitive)
  if printf '%s' "$value" | vercel env add "$name" production "${flags[@]}" >/dev/null 2>&1; then
    printf '  %s✓ set%s Vercel Production %s\n' "$GREEN" "$RESET" "$name"
    return
  fi
  if confirm "$name already exists in Vercel Production (or the add failed). Overwrite it?"; then
    if printf '%s' "$value" | vercel env add "$name" production "${flags[@]}" --force >/dev/null 2>&1; then
      printf '  %s✓ replaced%s Vercel Production %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("Vercel Production $name (vercel env add $name production)")
  warn "skipped $name"
}

# assert_preview_clean — stop if Vercel Preview holds a database or auth
# variable. Fails closed: if the list can't be read, that is a failure too.
assert_preview_clean() {
  local listing found=()
  if ! listing=$(vercel env list preview --cwd "$MAIN_ROOT" 2>/dev/null); then
    printf '  %s✗ could not read Vercel Preview variables%s\n' "$RED" "$RESET"
    exit 1
  fi
  for name in $PREVIEW_FORBIDDEN; do
    if printf '%s\n' "$listing" | grep -qE "^[[:space:]]*${name}[[:space:]]"; then found+=("$name"); fi
  done
  if (( ${#found[@]} )); then
    printf '  %s✗ Vercel Preview holds %s.%s\n' "$RED" "${found[*]}" "$RESET"
    say "Previews must have no database and no auth (SPEC C12). Remove them:"
    for name in "${found[@]}"; do step "vercel env rm $name preview"; done
    note "If the Neon integration is installed, turn off its Preview environment too."
    exit 1
  fi
  printf '  %s✓%s Vercel Preview has no database or auth variables\n' "$GREEN" "$RESET"
}

# production_branch_of — read a Vercel project JSON on stdin and print its
# productionBranch. Prints nothing if the field is missing, and every distinct
# value (one per line) if there is more than one, so callers can't be fooled.
production_branch_of() {
  # `|| true`: no match must print nothing, not abort under `set -o pipefail`.
  { grep -oE '"productionBranch"[[:space:]]*:[[:space:]]*"[^"]*"' || true; } | sed -E 's/.*"([^"]*)"$/\1/' | sort -u
}

# assert_production_branch_main — stop unless Vercel deploys production from
# main only (SPEC C12). Fails closed: an unreadable answer is a failure.
# MSYS_NO_PATHCONV stops Git Bash from rewriting "/v9/…" into a Windows path.
# It also stops it converting --cwd, which works because MAIN_ROOT comes from
# git as "D:/…" on Windows; a "/d/…" path would make the call fail (closed).
assert_production_branch_main() {
  local json branch
  if ! json=$(MSYS_NO_PATHCONV=1 vercel api "/v9/projects/$PROJECT_NAME" --cwd "$MAIN_ROOT" 2>/dev/null); then
    printf '  %s✗ could not read the Vercel project settings%s\n' "$RED" "$RESET"
    exit 1
  fi
  branch=$(printf '%s' "$json" | production_branch_of) || branch=""
  if [[ "$branch" != "main" ]]; then
    printf '  %s✗ Vercel production branch is "%s", not "main".%s\n' "$RED" "${branch:-unset}" "$RESET"
    step "Fix it: $PROJECT_NAME → Settings → Environments → Production → Branch Tracking → main."
    exit 1
  fi
  printf '  %s✓%s Vercel deploys production from main only\n' "$GREEN" "$RESET"
}

# warn_first_deploy — a new Vercel project's FIRST deployment is always a
# production deployment, whatever its branch (Vercel docs; it happened here,
# SPEC §B1). Warn unless a production deployment already exists. Only stdout
# counts (bare deployment URLs) and only on exit 0: stderr carries banners and
# update notices whose links must never read as "a deployment exists".
warn_first_deploy() {
  local out
  out=$(vercel ls "$PROJECT_NAME" --prod --cwd "$MAIN_ROOT" 2>/dev/null) || out=""
  if grep -qE '^https://' <<<"$out"; then
    printf '  %s✓%s A production deployment exists, so branch pushes cannot reach Production\n' "$GREEN" "$RESET"
    return
  fi
  warn "No production deployment yet. The FIRST deployment goes to Production with"
  warn "the production variables, from whatever branch triggers it."
  step "Make it from main: push or merge to main BEFORE pushing any other branch."
}

banner "Wanheda — GitHub sign-in and Vercel"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Preflight" 1
say "Checking the tools this wizard drives."
for tool in git gh vercel openssl; do
  if command -v "$tool" >/dev/null 2>&1; then
    printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$tool"
  else
    printf '  %s✗ %s is missing%s\n' "$RED" "$tool" "$RESET"
    exit 1
  fi
done
say "Vercel account: $(vercel whoami 2>/dev/null || echo 'not logged in')"
note "If that is not your account, stop now (Ctrl-C) and run: vercel login"
note "If this login predates 2026-10-11 (the worm), run: vercel logout && vercel login"
say "Local values go to: $ENV_FILE"
current_db=$(_existing DATABASE_URL || true)
if [[ -z "$current_db" ]]; then
  warn "No DATABASE_URL in $ENV_FILE. Add the pooled Neon URL there first, then re-run."
  exit 1
fi
say "Local database host: $(host_of "$current_db")"
pause "Press Enter to continue"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "GitHub OAuth app — local" 3
say "Create the OAuth app that localhost signs in with."
open_url "https://github.com/settings/applications/new"
step "Application name:            Wanheda (local)"
step "Homepage URL:                $LOCAL_URL"
step "Authorization callback URL:  $LOCAL_URL$CALLBACK_PATH"
step "Leave 'Enable Device Flow' off, then click Register application."
step "Copy the Client ID shown on the next page."
ask GITHUB_CLIENT_ID "Paste the local Client ID:"
step "Click 'Generate a new client secret' and copy it (GitHub shows it once)."
ask_secret GITHUB_CLIENT_SECRET "Paste the local client secret:"
write_env GITHUB_CLIENT_ID "$GITHUB_CLIENT_ID"
write_env GITHUB_CLIENT_SECRET "$GITHUB_CLIENT_SECRET"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Local auth settings" 2
local_secret=$(_existing BETTER_AUTH_SECRET || true)
if [[ -z "$local_secret" ]]; then
  local_secret=$(openssl rand -base64 32)
  say "Generated a new local BETTER_AUTH_SECRET (32 random bytes)."
else
  say "Keeping the existing local BETTER_AUTH_SECRET."
fi
write_env BETTER_AUTH_SECRET "$local_secret"
write_env BETTER_AUTH_URL "$LOCAL_URL"
write_env NEXT_PUBLIC_APP_URL "$LOCAL_URL"
say "Only these emails can create the owner account (comma-separated)."
note "Use the primary email of the GitHub account you will sign in with."
ask OWNER_EMAILS "Owner email(s):"
write_env OWNER_EMAILS "$OWNER_EMAILS"
if [[ -z "$(_existing DATABASE_URL_UNPOOLED || true)" ]]; then
  if [[ "$current_db" == *"-pooler."* ]]; then
    write_env DATABASE_URL_UNPOOLED "${current_db/-pooler./.}"
    note "Direct URL = the pooled URL without '-pooler' (host $(host_of "${current_db/-pooler./.}"))."
  else
    warn "DATABASE_URL has no '-pooler' host, so the direct URL can't be derived."
    step "Neon Console → your project → Connect → turn Connection pooling off → copy."
    ask_secret DATABASE_URL_UNPOOLED "Paste the direct (unpooled) URL:"
    write_env DATABASE_URL_UNPOOLED "$DATABASE_URL_UNPOOLED"
  fi
fi
pause "Press Enter to continue"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Vercel project — link and connect the repo" 3
say "This creates the Vercel project '$PROJECT_NAME' and links it to this repo."
note "Nothing deploys yet. The first push to main will, and it goes to Production."
note "Pushes to other branches deploy nothing (vercel.json git.deploymentEnabled)."
say "Answer the prompts like this:"
step "Set up the directory?            yes"
step "Which scope?                     your personal account"
step "Link to an existing project?     no"
step "Project name?                    $PROJECT_NAME"
step "Code directory?                  ./"
step "Modify the detected settings?    no"
step "Connect the Git repository?      yes (if asked)"
if confirm "Run 'vercel link' now?"; then
  vercel link --cwd "$MAIN_ROOT" || warn "vercel link did not finish; re-run the wizard to retry."
  # vercel link appends ".vercel" and ".env*" to .gitignore. Both are already
  # covered, and ".env*" after "!.env.example" would re-ignore .env.example.
  if ! git -C "$MAIN_ROOT" diff --quiet -- .gitignore; then
    git -C "$MAIN_ROOT" checkout -- .gitignore
    note "Undid the .gitignore lines vercel link added (already covered)."
  fi
  note "vercel link also adds a short-lived VERCEL_OIDC_TOKEN to .env.local (git-ignored)."
else
  SKIPPED+=("vercel link (run it in $MAIN_ROOT)")
fi
say "Now check the Git connection."
open_url "https://vercel.com/dashboard"
step "Open $PROJECT_NAME → Settings → Git."
step "Connected Git Repository must be your wanheda GitHub repo, production branch main."
if ! confirm "Is the repo connected?"; then
  if confirm "Run 'vercel git connect' now?"; then
    vercel git connect --cwd "$MAIN_ROOT" || SKIPPED+=("vercel git connect")
  else
    SKIPPED+=("connect the Git repo (vercel git connect)")
  fi
fi
assert_production_branch_main
warn_first_deploy
pause "Press Enter to continue"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Production URL and GitHub OAuth app — production" 3
step "In Vercel: $PROJECT_NAME → Settings → Domains. Copy the .vercel.app domain."
note "Passkeys bind to this host. Changing it later means registering passkeys again."
ask PROD_URL "Production URL (https://….vercel.app):"
PROD_URL="${PROD_URL%/}"
if [[ "$PROD_URL" != https://* ]]; then
  warn "The production URL must start with https://"
  exit 1
fi
say "Now the OAuth app that production signs in with."
open_url "https://github.com/settings/applications/new"
step "Application name:            Wanheda"
step "Homepage URL:                $PROD_URL"
step "Authorization callback URL:  $PROD_URL$CALLBACK_PATH"
step "Register, then copy the Client ID."
ask PROD_GITHUB_CLIENT_ID "Paste the production Client ID:"
step "Generate a new client secret and copy it."
ask_secret PROD_GITHUB_CLIENT_SECRET "Paste the production client secret:"
note "Kept in memory only, for the Vercel step. Not written to $ENV_FILE."

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Database URLs — Production only" 1
say "Production uses the same Neon database as $ENV_FILE (host $(host_of "$current_db"))."
note "No Neon <-> Vercel integration: its preview branches would copy production's rows"
note "into builds of unreviewed branches (ADR-0002). Previews get no database."
if confirm "Write DATABASE_URL and DATABASE_URL_UNPOOLED to Vercel Production (sensitive)?"; then
  vercel_env_set DATABASE_URL "$current_db" sensitive
  vercel_env_set DATABASE_URL_UNPOOLED "$(_existing DATABASE_URL_UNPOOLED)" sensitive
else
  SKIPPED+=("Vercel Production DATABASE_URL(_UNPOOLED) (re-run the wizard)")
fi
assert_preview_clean

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Vercel production variables" 2
say "These go to Vercel Production only. Previews get none, so they run demo mode."
step "BETTER_AUTH_SECRET    a new random secret, different from the local one"
step "BETTER_AUTH_URL       $PROD_URL"
step "NEXT_PUBLIC_APP_URL   $PROD_URL"
step "GITHUB_CLIENT_ID      the production app's Client ID"
step "GITHUB_CLIENT_SECRET  the production app's secret"
step "OWNER_EMAILS          $OWNER_EMAILS"
if confirm "Write these 6 variables to Vercel Production now?"; then
  vercel_env_set BETTER_AUTH_SECRET "$(openssl rand -base64 32)" sensitive
  vercel_env_set BETTER_AUTH_URL "$PROD_URL"
  vercel_env_set NEXT_PUBLIC_APP_URL "$PROD_URL"
  vercel_env_set GITHUB_CLIENT_ID "$PROD_GITHUB_CLIENT_ID"
  vercel_env_set GITHUB_CLIENT_SECRET "$PROD_GITHUB_CLIENT_SECRET" sensitive
  vercel_env_set OWNER_EMAILS "$OWNER_EMAILS"
else
  SKIPPED+=("Vercel Production auth variables (re-run the wizard)")
fi
unset PROD_GITHUB_CLIENT_SECRET
say "Variables in Vercel Production (names only):"
vercel env list production --cwd "$MAIN_ROOT" 2>/dev/null || true
assert_preview_clean
pause "Press Enter to continue"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Try sign-in locally" 3
say "In another terminal, in $MAIN_ROOT:"
step "bun run dev"
open_url "$LOCAL_URL"
step "You land on /login. Sign in with GitHub as the owner."
step "On the home page, click 'Add passkey', then sign out and sign in with it."
note "A GitHub account whose email is not in OWNER_EMAILS must be refused."
pause "Press Enter when done (or to skip)"

finish
say "Next: tell the Builder session the wizard is done and give it the production URL."
say "Production deploys when the Checkpoint 3 PR is merged into main."
